package com.example.sumayerestaurant.ui.customer;
import android.os.Bundle;import android.text.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.sumayerestaurant.data.api.RetrofitClient;import com.example.sumayerestaurant.data.local.TokenManager;import com.example.sumayerestaurant.data.model.*;import java.util.*;import retrofit2.*;
/** Search-first customer selection and quick customer creation, in Kiswahili. */
public class CustomerActivity extends AppCompatActivity{private LinearLayout results;private EditText name,phone,address,search;private Long branchId;@Override public void onCreate(Bundle b){super.onCreate(b);User u=new TokenManager(this).getUser();branchId=(u==null||u.getBranchId()==null)?1L:u.getBranchId();setTitle("Wateja");LinearLayout root=new LinearLayout(this);root.setPadding(32,32,32,32);root.setOrientation(LinearLayout.VERTICAL);search=field("Tafuta kwa jina au namba ya simu");root.addView(search);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);root.addView(results);name=field("Jina kamili");phone=field("Namba ya simu, mfano 0712345678");address=field("Anwani (si lazima)");root.addView(name);root.addView(phone);root.addView(address);Button add=new Button(this);add.setText("Ongeza mteja");root.addView(add);setContentView(root);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){load(s.toString());}public void afterTextChanged(Editable e){}});add.setOnClickListener(v->create());load("");}private EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setMinHeight(96);return e;}private void load(String q){if(branchId==null)return;RetrofitClient.getApiService(this).searchCustomers(branchId,q,0,20).enqueue(new Callback<PageResponse<Customer>>(){public void onResponse(Call<PageResponse<Customer>>c,Response<PageResponse<Customer>>r){results.removeAllViews();if(!r.isSuccessful()||r.body()==null||r.body().getContent()==null){show("Hakuna wateja waliopatikana.");return;}for(Customer x:r.body().getContent()){TextView v=new TextView(CustomerActivity.this);v.setText(x.toString());v.setPadding(12,20,12,20);v.setTextSize(17);results.addView(v);}}public void onFailure(Call<PageResponse<Customer>>c,Throwable t){show("Hakuna mtandao. Tafadhali jaribu tena.");}});}private void create(){if(branchId==null||name.getText().toString().trim().isEmpty()||phone.getText().toString().trim().isEmpty()){toast("Weka jina na namba ya simu.");return;}Map<String,Object> x=new HashMap<>();x.put("fullName",name.getText().toString().trim());x.put("phoneNumber",phone.getText().toString().trim());x.put("address",address.getText().toString().trim());RetrofitClient.getApiService(this).createCustomer(branchId,x).enqueue(new Callback<Customer>(){public void onResponse(Call<Customer>c,Response<Customer>r){if(r.isSuccessful()){toast("Mteja ameongezwa.");name.setText("");phone.setText("");address.setText("");load("");}else toast("Imeshindikana kuhifadhi. Hakiki namba ya simu.");}public void onFailure(Call<Customer>c,Throwable t){toast("Hakuna mtandao. Tafadhali jaribu tena.");}});}private void show(String s){TextView x=new TextView(this);x.setText(s);results.addView(x);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}}
